import queue

import pytest


def accepted(cap: int, xs: list[int]) -> int:
    """Count puts accepted by a bounded queue before it is full.

    Creates a queue holding at most `cap` integers and tries to put each
    element of `xs` in order without blocking. Stops at the first rejected
    put (queue full) and returns the number of puts accepted before that.
    Nothing is ever taken from the queue. A capacity of 0 or less accepts
    nothing, so the result is 0 (not an unbounded queue).
    """
    if cap <= 0:
        return 0
    q: queue.Queue[int] = queue.Queue(maxsize=cap)
    count = 0
    for x in xs:
        try:
            q.put_nowait(x)
        except queue.Full:
            break
        count += 1
    return count


def test_more_items_than_capacity() -> None:
    assert accepted(2, [1, 2, 3, 4]) == 2


def test_fewer_items_than_capacity() -> None:
    assert accepted(5, [1, 2, 3]) == 3


def test_exact_fit() -> None:
    assert accepted(3, [7, 8, 9]) == 3


def test_empty_input() -> None:
    assert accepted(4, []) == 0


def test_zero_capacity() -> None:
    assert accepted(0, [1, 2, 3]) == 0


def test_negative_capacity() -> None:
    assert accepted(-1, [1, 2]) == 0


def test_capacity_one() -> None:
    assert accepted(1, [5, 5, 5]) == 1


def test_duplicates_are_counted() -> None:
    assert accepted(3, [1, 1, 1, 1]) == 3


@pytest.mark.parametrize(
    ("cap", "xs", "expected"),
    [
        (1, [1], 1),
        (2, [1], 1),
        (3, list(range(10)), 3),
        (10, list(range(10)), 10),
        (0, [], 0),
    ],
)
def test_parametrized(cap: int, xs: list[int], expected: int) -> None:
    assert accepted(cap, xs) == expected


def test_does_not_mutate_input() -> None:
    xs = [1, 2, 3, 4]
    accepted(2, xs)
    assert xs == [1, 2, 3, 4]

